#!/bin/sh
# Pawline Needle bench for the Dell - one command, honest labels.
# Usage:   sh tools/dell_bench.sh
# Output:  dell-bench-results.txt in the repo root - send that file back.
# Runs one config at a time and caps generation at 64 tokens, so it fits
# the Dell's 6 GB and stays interruptible. Expect a few minutes total.
set -e
cd "$(dirname "$0")/.."
OUT=dell-bench-results.txt

{
echo "Pawline needle bench - $(date -u '+%Y-%m-%d %H:%M UTC')"
echo "== machine =="
uname -a
grep -m1 "model name" /proc/cpuinfo
printf 'SIMD flags: '
grep -m1 flags /proc/cpuinfo | tr ' ' '\n' | grep -E '^(sse4_2|avx|avx2|fma|f16c)$' | tr '\n' ' '
echo
free -h | sed -n 1,2p
} > "$OUT"

echo "== build ==" | tee -a "$OUT"
cargo build --release -p pawline-needle --example dump_tools \
    -p pawline-needle-native --example bench --example simd_check 2>&1 | tail -2 | tee -a "$OUT"
./target/release/examples/dump_tools | tee -a "$OUT"

{
echo "== dispatch =="
./target/release/examples/simd_check
echo "== bench (64 new tokens cap, one config at a time) =="
} >> "$OUT" 2>&1

for cfg in "d20 f32" "d20 int8" "d12"; do
    echo "-- $cfg --" >> "$OUT"
    BENCH_MAX_NEW=64 ./target/release/examples/bench "$cfg" >> "$OUT" 2>&1
done


# == vision timing (optional) ==
# Times the live vision path through a running llama-server, using the same
# synthetic quadrant probes as docs/EXPERIMENTS.md 4b/4c. Run it once with a
# SmolVLM-256M server and once with a 500M server (model name is read from
# the server) to get a like-for-like Dell comparison. Skipped cleanly when
# no server answers.
echo "== vision timing (optional) ==" >> "$OUT"
VISION_URL="${VISION_URL:-http://127.0.0.1:8080}"
if ! curl -fsS -m 2 "$VISION_URL/health" >/dev/null 2>&1; then
    {
    echo "skipped: no llama-server at $VISION_URL"
    echo "  to run: llama-server -m <SmolVLM GGUF> --mmproj <mmproj GGUF> -c 4096"
    echo "  then re-run this script (set VISION_URL=http://host:port if not :8080)"
    } >> "$OUT"
else
    TMPV=$(mktemp -d)
    sed -n '/^__B64_256__$/,/^__END_256__$/p' "$0" | sed '1d;$d' | base64 -d > "$TMPV/small.png"
    sed -n '/^__B64_1024__$/,/^__END_1024__$/p' "$0" | sed '1d;$d' | base64 -d > "$TMPV/big.png"
    {
    echo "server: $VISION_URL"
    curl -fsS -m 2 "$VISION_URL/props" 2>/dev/null | grep -o '"model_path":"[^"]*"' | sed 's/^/  /'
    } >> "$OUT" || true
    vision_probe() {
        name="$1"; png="$2"; prompt="$3"
        b64=$(base64 -w0 "$png")
        printf '{"messages":[{"role":"user","content":[{"type":"text","text":"%s"},{"type":"image_url","image_url":{"url":"data:image/png;base64,%s"}}]}],"max_tokens":60,"temperature":0}' \
            "$prompt" "$b64" > "$TMPV/body.json"
        secs=$(curl -fsS -m 600 -o "$TMPV/resp.json" -w '%{time_total}' \
            -H 'Content-Type: application/json' -d @"$TMPV/body.json" \
            "$VISION_URL/v1/chat/completions" 2>/dev/null) || secs="FAILED"
        ptok=$(grep -o '"prompt_tokens":[0-9]*' "$TMPV/resp.json" 2>/dev/null | head -1 | cut -d: -f2)
        ctok=$(grep -o '"completion_tokens":[0-9]*' "$TMPV/resp.json" 2>/dev/null | head -1 | cut -d: -f2)
        ans=$(grep -o '"content":"[^"]*"' "$TMPV/resp.json" 2>/dev/null | head -1 | cut -c12-200)
        echo "-- $name: ${secs}s, prompt_tokens=$ptok completion_tokens=$ctok" >> "$OUT"
        echo "   answer: $ans" >> "$OUT"
    }
    if [ -s "$TMPV/small.png" ] && [ -s "$TMPV/big.png" ]; then
        vision_probe "256px simple-description" "$TMPV/small.png" "Describe this image in one sentence."
        vision_probe "1024px quadrant-colors" "$TMPV/big.png" "What are the four background colors in this image? Answer as a short list."
    else
        echo "skipped: could not decode embedded test images" >> "$OUT"
    fi
    rm -rf "$TMPV"
fi

echo "Done. Results in $OUT - send that file back."
exit 0

__B64_256__

__END_256__
__B64_1024__

__END_1024__

